export const FAST_WINDOW = 1024;

// Strict YIN on the newest audio, independent of the longer polyphonic fit.
// A measured fundamental is required: a common period of a major chord must
// not invent a bass note that is absent from the signal.
export const createFastPitchDetector = (rate: number) => {
  const size = FAST_WINDOW / 2;
  const maxLag = Math.min(size - 1, Math.ceil(rate / 40));
  const difference = new Float32Array(maxLag + 1);
  const centered = new Float32Array(FAST_WINDOW);
  const hann = Float32Array.from(
    { length: FAST_WINDOW },
    (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / FAST_WINDOW),
  );
  const amplitude = (frequency: number) => {
    let real = 0,
      imaginary = 0;
    for (let i = 0; i < FAST_WINDOW; i++) {
      const phase = (2 * Math.PI * frequency * i) / rate;
      real += centered[i] * hann[i] * Math.cos(phase);
      imaginary += centered[i] * hann[i] * Math.sin(phase);
    }
    return (Math.hypot(real, imaginary) * 4) / FAST_WINDOW;
  };
  let previous: { midi: number; frequency: number } | undefined;
  let level = 0;
  const upperHistory: number[] = [];
  let octaveAttack = 0;
  return {
    get level() {
      return level;
    },
    reset() {
      previous = undefined;
      upperHistory.length = 0;
      octaveAttack = 0;
    },
    analyze(samples: Float32Array) {
      let mean = 0,
        energy = 0;
      samples.forEach(value => {
        mean += value;
      });
      mean /= samples.length;
      for (let i = 0; i < FAST_WINDOW; i++) {
        centered[i] = samples[i] - mean;
        energy += centered[i] ** 2;
      }
      const rms = Math.sqrt(energy / FAST_WINDOW);
      level = rms * rms;
      const upper = previous ? amplitude(previous.frequency * 2) : 0;
      if (
        upperHistory.length === 3 &&
        upper > Math.max(0.002, upperHistory[0] * 1.35) &&
        upper > upperHistory[2] * 1.05
      )
        octaveAttack = 6;
      else if (octaveAttack) octaveAttack--;
      upperHistory.push(upper);
      if (upperHistory.length > 3) upperHistory.shift();
      if (rms < 0.006) return null;
      let cumulative = 0;
      for (let lag = 1; lag <= maxLag; lag++) {
        let sum = 0;
        for (let i = 0; i < size; i++)
          sum += (centered[i] - centered[i + lag]) ** 2;
        cumulative += sum;
        difference[lag] = cumulative ? (sum * lag) / cumulative : 1;
      }
      for (
        let lag = Math.max(2, Math.floor(rate / 2000));
        lag < maxLag;
        lag++
      ) {
        if (difference[lag] >= 0.04) continue;
        while (lag + 1 < maxLag && difference[lag + 1] < difference[lag]) lag++;
        const denominator =
          difference[lag - 1] - 2 * difference[lag] + difference[lag + 1];
        const shift = denominator
          ? (difference[lag - 1] - difference[lag + 1]) / (2 * denominator)
          : 0;
        let frequency = rate / (lag + Math.max(-1, Math.min(1, shift)));
        let midi = Math.round(69 + 12 * Math.log2(frequency / 440));
        if (midi < 28 || midi > 95) return null;
        let retained = false;
        if (
          !octaveAttack &&
          previous &&
          midi > previous.midi &&
          (midi - previous.midi) % 12 === 0
        ) {
          const lower = frequency / 2 ** ((midi - previous.midi) / 12);
          if (
            [1, 3, 5].some(
              harmonic =>
                amplitude(lower * harmonic) >= Math.max(0.00015, rms * 0.03),
            )
          ) {
            frequency = lower;
            midi = previous.midi;
            retained = true;
          }
        }
        const strength = amplitude(frequency);
        if (!retained && strength < Math.max(0.002, rms * 0.18)) return null;
        if (previous?.midi !== midi) upperHistory.length = 0;
        previous = { midi, frequency };
        return {
          midi,
          frequency,
          strength: retained ? Math.max(strength, rms * 0.25) : strength,
        };
      }
      return null;
    },
  };
};
