import { FAST_WINDOW } from './fastPitch';
import { POLY_SAMPLE_RATE } from './pitchSpectrum';

type Envelope = { time: number; partials: number[] };
export type PitchOnset = { time: number; independent: boolean };

// A short, pitch-specific envelope supplies timing only. Pitch selection stays
// with the pitch detectors; an overtone rising with its parent is not a pick.
export const createPitchOnsets = () => {
  const hann = Float32Array.from(
    { length: FAST_WINDOW },
    (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / FAST_WINDOW),
  );
  const bands = Array.from({ length: 68 }, (_, i) =>
    [1, 2, 3].map(harmonic =>
      [-20, 0, 20].flatMap(cents => {
        const frequency = 440 * 2 ** ((i + 28 - 69 + cents / 100) / 12);
        return frequency * harmonic < POLY_SAMPLE_RATE / 2
          ? [
              2 *
                Math.cos(
                  (2 * Math.PI * frequency * harmonic) / POLY_SAMPLE_RATE,
                ),
            ]
          : [];
      }),
    ),
  );
  const history: Envelope[][] = bands.map(() => []);
  const onsets = new Map<number, PitchOnset>();
  const weighted = new Float32Array(FAST_WINDOW);
  let previousEnergy = 0;
  let transient = -Infinity;
  const analyze = (samples: Float32Array, end: number) => {
    let energy = 0;
    samples.forEach(value => {
      energy += value * value;
    });
    if (energy > previousEnergy * 1.2) transient = end;
    previousEnergy = energy;
    for (let i = 0; i < samples.length; i++) weighted[i] = samples[i] * hann[i];
    const attacks: { midi: number; time: number; strength: number }[] = [];
    bands.forEach((partials, index) => {
      const levels = partials.map(coefficients => {
        let largest = 0;
        coefficients.forEach(coefficient => {
          let a = 0,
            b = 0;
          for (let i = 0; i < weighted.length; i++) {
            const next = weighted[i] + coefficient * a - b;
            b = a;
            a = next;
          }
          largest = Math.max(
            largest,
            (Math.sqrt(Math.max(0, a * a + b * b - coefficient * a * b)) * 4) /
              FAST_WINDOW,
          );
        });
        return largest;
      });
      const previous = history[index];
      const baseline = previous.length
        ? previous.reduce((quietest, frame) =>
            frame.partials[0] < quietest.partials[0] ? frame : quietest,
          )
        : { time: end - 40, partials: [0, 0, 0] };
      const last = previous[previous.length - 1];
      const midi = index + 28;
      if (
        levels[0] > Math.max(0.008, baseline.partials[0] * 1.5) &&
        (!last || levels[0] > last.partials[0] * 1.08) &&
        levels
          .slice(1)
          .some(
            (value, h) =>
              value > Math.max(0.003, baseline.partials[h + 1] * 1.3),
          ) &&
        end - (onsets.get(midi)?.time ?? -Infinity) > 160
      ) {
        const first = previous.find(
          frame =>
            frame.time > baseline.time &&
            frame.partials[0] > Math.max(0.004, baseline.partials[0] * 1.4),
        );
        attacks.push({
          midi,
          time:
            (first?.time ?? end) - (FAST_WINDOW / 2 / POLY_SAMPLE_RATE) * 1000,
          strength: levels[0],
        });
      }
      previous.push({ time: end, partials: levels });
      if (previous.length > 3) previous.shift();
    });
    attacks.forEach(attack => {
      const parent = attacks.some(lower => {
        if (lower.midi >= attack.midi || lower.strength < attack.strength * 0.5)
          return false;
        const ratio = 2 ** ((attack.midi - lower.midi) / 12);
        return (
          Math.abs(1200 * Math.log2(ratio / Math.round(ratio))) < 18 &&
          Math.abs(lower.time - attack.time) <= 80
        );
      });
      onsets.set(attack.midi, {
        time: Math.max(0, attack.time),
        independent: !parent && end - transient <= 80,
      });
    });
  };
  return {
    analyze,
    get(midi: number, end: number) {
      const onset = onsets.get(midi);
      return onset && end >= onset.time && end - onset.time <= 640
        ? onset
        : undefined;
    },
    reset() {
      history.forEach(frames => {
        frames.length = 0;
      });
      onsets.clear();
      previousEnergy = 0;
      transient = -Infinity;
    },
  };
};
