import { chordQualities } from 'app/services/ChordsService';

import type { PitchActivation } from './polyphonicPitch';

const masks = Array.from(
  new Set(
    Object.values(chordQualities).flatMap(quality => {
      const intervals: readonly number[] = quality.intervals;
      return Array.from({ length: 12 }, (_, root) =>
        intervals.reduce(
          (mask, interval) => mask | (1 << (root + interval) % 12),
          0,
        ),
      );
    }),
  ),
);

// A clear chord can reject weak unrelated spectral residues. Unknown sets and
// strong added tones remain unconstrained; this never creates missing voices.
export const createPolyphonicConfidence = () => {
  let previous: number | undefined;
  let held = 0;
  let lastConfirmed: number | undefined;
  let pending: number | undefined;
  let pendingFrames = 0;
  return {
    reset() {
      previous = lastConfirmed = pending = undefined;
      held = pendingFrames = 0;
    },
    filter(pitches: PitchActivation[]) {
      const chroma = new Float32Array(12);
      pitches.forEach(pitch => {
        chroma[pitch.midi % 12] = Math.max(
          chroma[pitch.midi % 12],
          pitch.strength,
        );
      });
      const maximum = Math.max(0, ...Array.from(chroma));
      const total = chroma.reduce((sum, value) => sum + value * value, 0);
      const fits = masks
        .map(mask => {
          let power = 0,
            complete = true,
            strongOutside = false;
          chroma.forEach((value, index) => {
            if (mask & (1 << index)) {
              power += value * value;
              if (value < maximum * 0.12) complete = false;
            } else if (value > maximum * 0.65) strongOutside = true;
          });
          return {
            mask,
            score: total && complete && !strongOutside ? power / total : 0,
          };
        })
        .sort((a, b) => b.score - a.score);
      const best = fits[0];
      const candidate =
        best.score >= 0.88 && best.score - fits[1].score >= 0.05;
      if (candidate && pending === best.mask) pendingFrames++;
      else {
        pending = candidate ? best.mask : undefined;
        pendingFrames = candidate ? 1 : 0;
      }
      const balanced =
        best.score >= 0.97 &&
        chroma.every(
          (value, index) =>
            !(best.mask & (1 << index)) || value >= maximum * 0.5,
        );
      const required =
        balanced && (lastConfirmed === undefined || lastConfirmed === best.mask)
          ? 1
          : 5;
      const confident = candidate && pendingFrames >= required;
      if (confident) {
        previous = lastConfirmed = best.mask;
        held = 3;
      } else if (held) held--;
      else previous = undefined;
      return {
        pitches:
          previous === undefined
            ? pitches
            : pitches.filter(pitch => previous! & (1 << pitch.midi % 12)),
        frames: confident ? 2 : 5,
      };
    },
  };
};
