// A harmonic dictionary groups partials into candidate notes. NNLS and sparse
// model selection reduce overtone and octave doubling.
// See docs/GUITAR_INPUT.md for the method and its limits.
import {
  FundamentalEvidence,
  createMonophonicEvidence,
} from './monophonicEvidence';
import { POLY_SAMPLE_RATE, POLY_WINDOW, createSpectrum } from './pitchSpectrum';
import audioProfiles from './pitchTemplates.json';

export { POLY_SAMPLE_RATE, POLY_WINDOW } from './pitchSpectrum';
export const POLY_HOP = 480;
const FIRST_MIDI = 28;
const LAST_MIDI = 95;
const MAX_VOICES = 8;

type Template = { midi: number; bins: Uint16Array; weights: Float32Array };
export type PitchActivation = { midi: number; strength: number };

const hannLobe = (offset: number) => {
  if (Math.abs(offset) < 1e-7) return 1;
  if (Math.abs(Math.abs(offset) - 1) < 1e-7) return 0.5;
  return Math.abs(
    Math.sin(Math.PI * offset) / (Math.PI * offset * (1 - offset * offset)),
  );
};

const makeTemplates = (midi: number, frequency: number): Template[] => {
  const result: Template[] = [];
  const profiles = [
    [0.55, 1],
    [0.7, 1],
    [0.85, 1],
    [0.7, 0.25],
    [0, 1],
  ];
  const harmonics = profiles.map(([decay, fundamental]) =>
    Array.from({ length: 15 }, (_, i) => (i === 0 ? fundamental : decay ** i)),
  );
  harmonics.push(
    ...audioProfiles.profiles[midi - FIRST_MIDI].map(profile =>
      profile.map(value => value / 1000),
    ),
  );
  for (const profile of harmonics) {
    const values = new Map<number, number>();
    for (let harmonic = 1; harmonic <= 15; harmonic++) {
      const amplitude = profile[harmonic - 1];
      const center = (frequency * harmonic * POLY_WINDOW) / POLY_SAMPLE_RATE;
      if (center >= POLY_WINDOW / 2) break;
      if (amplitude < 0.003) continue;
      for (
        let bin = Math.max(1, Math.floor(center) - 3);
        bin <= Math.min(POLY_WINDOW / 2 - 1, Math.ceil(center) + 3);
        bin++
      ) {
        const value = amplitude * hannLobe(bin - center);
        if (value > 0.003) values.set(bin, (values.get(bin) ?? 0) + value);
      }
    }
    const bins = Uint16Array.from(values.keys());
    const weights = Float32Array.from(values.values());
    let norm = 0;
    weights.forEach(value => {
      norm += value * value;
    });
    norm = Math.sqrt(norm);
    for (let i = 0; i < weights.length; i++) weights[i] /= norm;
    result.push({ midi, bins, weights });
  }
  return result;
};

export const createPolyphonicPitchDetector = () => {
  const tunings = new Float64Array(LAST_MIDI - FIRST_MIDI + 1);
  const offsets: number[] = [];
  const dictionary: Template[] = [];
  for (let midi = FIRST_MIDI; midi <= LAST_MIDI; midi++) {
    const frequency = 440 * 2 ** ((midi - 69) / 12);
    tunings[midi - FIRST_MIDI] = frequency;
    offsets.push(dictionary.length);
    dictionary.push(...makeTemplates(midi, frequency));
  }
  const spectrum = createSpectrum();
  const coefficients = new Float32Array(dictionary.length);
  const residual = new Float32Array(POLY_WINDOW / 2);
  const scores = new Float32Array(LAST_MIDI - FIRST_MIDI + 1);
  const eligible = new Uint8Array(scores.length);
  const frequencySupported = new Uint8Array(scores.length);
  const monophonic = createMonophonicEvidence(POLY_SAMPLE_RATE, POLY_WINDOW);
  const analyze = (samples: Float32Array): PitchActivation[] => {
    const magnitudes = spectrum(samples);
    let power = 0,
      logs = 0,
      count = 0;
    for (let i = 14; i < 1400; i++) {
      const value = magnitudes[i] ** 2;
      power += value;
      logs += Math.log(Math.max(1e-12, value));
      count++;
    }
    if (power < 1e-6 || Math.exp(logs / count) / (power / count) > 0.3) {
      coefficients.fill(0);
      monophonic.reset();
      return [];
    }
    let peak = 0;
    magnitudes.forEach(value => {
      peak = Math.max(peak, value);
    });
    const fundamentals: FundamentalEvidence[] = [];
    for (let midi = FIRST_MIDI; midi <= LAST_MIDI; midi++) {
      const ideal = 440 * 2 ** ((midi - 69) / 12);
      const cents: number[] = [];
      let fundamental = 0;
      let fundamentalMatched = false;
      let fundamentalCents: number | undefined;
      for (let harmonic = 1; harmonic <= 4; harmonic++) {
        const center = (ideal * harmonic * POLY_WINDOW) / POLY_SAMPLE_RATE;
        if (center >= magnitudes.length - 2) break;
        const radius = Math.max(2, Math.ceil(center * 0.022));
        let bin = Math.max(1, Math.round(center));
        for (
          let i = Math.max(1, Math.ceil(center - radius));
          i <= Math.min(magnitudes.length - 2, Math.floor(center + radius));
          i++
        ) {
          if (magnitudes[i] > magnitudes[bin]) bin = i;
        }
        if (harmonic === 1) fundamental = magnitudes[bin];
        if (
          magnitudes[bin] < peak * 0.025 ||
          magnitudes[bin] < magnitudes[bin - 1] ||
          magnitudes[bin] < magnitudes[bin + 1]
        )
          continue;
        const left = Math.log(Math.max(1e-12, magnitudes[bin - 1]));
        const middle = Math.log(Math.max(1e-12, magnitudes[bin]));
        const right = Math.log(Math.max(1e-12, magnitudes[bin + 1]));
        const denominator = left - 2 * middle + right;
        const shift = denominator
          ? Math.max(-0.5, Math.min(0.5, (left - right) / (2 * denominator)))
          : 0;
        const frequency =
          ((bin + shift) * POLY_SAMPLE_RATE) / POLY_WINDOW / harmonic;
        const deviation = 1200 * Math.log2(frequency / ideal);
        if (Math.abs(deviation) <= 40) {
          cents.push(deviation);
          if (harmonic === 1) {
            fundamentalMatched = true;
            fundamentalCents = deviation;
          }
        }
      }
      eligible[midi - FIRST_MIDI] =
        fundamental >= Math.max(0.002, peak * 0.08) &&
        (fundamental >= peak * 0.5 ||
          (fundamentalCents !== undefined &&
            cents.filter(value => Math.abs(value - fundamentalCents!) <= 12)
              .length >= 2))
          ? 1
          : 0;
      frequencySupported[midi - FIRST_MIDI] =
        fundamentalMatched || cents.length >= 2 ? 1 : 0;
      if (eligible[midi - FIRST_MIDI] && cents.length) {
        cents.sort((a, b) => a - b);
        const tuning = Math.round(cents[Math.floor(cents.length / 2)] / 2) * 2;
        const frequency = ideal * 2 ** (tuning / 1200);
        if (
          Math.abs(1200 * Math.log2(frequency / tunings[midi - FIRST_MIDI])) > 1
        ) {
          tunings[midi - FIRST_MIDI] = frequency;
          const updated = makeTemplates(midi, frequency);
          updated.forEach((template, index) => {
            dictionary[offsets[midi - FIRST_MIDI] + index] = template;
          });
        }
      }
      if (fundamentalMatched)
        fundamentals.push({
          midi,
          frequency: tunings[midi - FIRST_MIDI],
          amplitude: fundamental,
        });
    }
    const fit = (
      allowed: Uint8Array,
      values: Float32Array,
      iterations: number,
    ) => {
      residual.set(magnitudes);
      for (let column = 0; column < dictionary.length; column++) {
        const { bins, weights } = dictionary[column];
        if (!allowed[dictionary[column].midi - FIRST_MIDI]) {
          values[column] = 0;
          continue;
        }
        const coefficient = values[column];
        if (coefficient)
          for (let i = 0; i < bins.length; i++)
            residual[bins[i]] -= coefficient * weights[i];
      }
      for (let iteration = 0; iteration < iterations; iteration++) {
        let movement = 0;
        for (let column = 0; column < dictionary.length; column++) {
          const { bins, weights } = dictionary[column];
          if (!allowed[dictionary[column].midi - FIRST_MIDI]) continue;
          let gradient = 0;
          for (let i = 0; i < bins.length; i++)
            gradient += weights[i] * residual[bins[i]];
          const value = Math.max(0, values[column] + gradient - 0.0015);
          const delta = value - values[column];
          movement = Math.max(movement, Math.abs(delta));
          if (Math.abs(delta) < 1e-7) continue;
          values[column] = value;
          for (let i = 0; i < bins.length; i++)
            residual[bins[i]] -= delta * weights[i];
        }
        if (movement < 0.00015) break;
      }
      let error = 0;
      for (let i = 0; i < residual.length; i++)
        error += residual[i] * residual[i];
      return error;
    };
    fit(eligible, coefficients, 45);
    scores.fill(0);
    for (let i = 0; i < dictionary.length; i++)
      scores[dictionary[i].midi - FIRST_MIDI] += coefficients[i];
    let maximum = 0;
    scores.forEach(value => {
      maximum = Math.max(maximum, value);
    });
    const selected = Array.from(scores, (strength, index) => ({
      midi: FIRST_MIDI + index,
      strength,
    }))
      .filter(item => item.strength >= Math.max(0.008, maximum * 0.2))
      .sort((a, b) => b.strength - a.strength)
      .slice(0, MAX_VOICES);
    const allowed = new Uint8Array(eligible.length);
    selected.forEach(item => {
      allowed[item.midi - FIRST_MIDI] = 1;
    });
    let best = coefficients.slice();
    let error = fit(allowed, best, 35);
    let total = 0;
    magnitudes.forEach(value => {
      total += value * value;
    });
    const span = selected.length
      ? Math.max(...selected.map(item => item.midi)) -
        Math.min(...selected.map(item => item.midi))
      : 0;
    // Dense guitar voicings share many partials across two octaves. Use a
    // conservative model-selection penalty there to preserve doubled voices.
    const penalty = selected.length >= 6 && span >= 20 ? 0.0002 : 0.008;
    // Prefer the smaller set when removing a voice barely changes the fit.
    // This distinguishes a strong overtone from an independently needed note.
    for (const item of selected.slice().reverse()) {
      if (selected.filter(note => allowed[note.midi - FIRST_MIDI]).length <= 1)
        break;
      allowed[item.midi - FIRST_MIDI] = 0;
      const trial = best.slice();
      const trialError = fit(allowed, trial, 35);
      const lower = selected.find(
        other =>
          allowed[other.midi - FIRST_MIDI] && other.midi === item.midi - 12,
      );
      const weakOctave =
        selected.length === 2 && lower && item.strength < lower.strength * 0.5;
      if (weakOctave || trialError - error < total * penalty) {
        best = trial;
        error = trialError;
      } else allowed[item.midi - FIRST_MIDI] = 1;
    }
    coefficients.set(best);
    scores.fill(0);
    for (let i = 0; i < dictionary.length; i++)
      scores[dictionary[i].midi - FIRST_MIDI] += best[i];
    const pitches = selected
      .filter(item => allowed[item.midi - FIRST_MIDI])
      .map(item => ({
        midi: item.midi,
        strength: scores[item.midi - FIRST_MIDI],
      }))
      .sort((a, b) => a.midi - b.midi);
    // A wide attack lobe can cover two neighboring semitones. Require a
    // matching peak/partial series before adding the weaker neighbor.
    const supported = pitches.filter(
      pitch =>
        frequencySupported[pitch.midi - FIRST_MIDI] ||
        !fundamentals.some(
          other =>
            Math.abs(other.midi - pitch.midi) === 1 &&
            other.amplitude >= peak * 0.08,
        ),
    );
    return monophonic.filter(magnitudes, fundamentals, supported);
  };
  return Object.assign(analyze, {
    reset() {
      coefficients.fill(0);
      monophonic.reset();
    },
  });
};
